import WidgetKit
import SwiftUI

struct WeatherEntry: TimelineEntry {
    let date: Date
    let temperature: Double
}

struct WeatherProvider: TimelineProvider {
    func placeholder(in context: Context) -> WeatherEntry {
        WeatherEntry(date: .now, temperature: 0)
    }

    func getSnapshot(in context: Context, completion: @escaping (WeatherEntry) -> ()) {
        completion(WeatherEntry(date: .now, temperature: 12.0))
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<WeatherEntry>) -> ()) {
        let url = URL(string: "https://api.weatherapi.com/v1/current.json?key=DEMO&q=Berlin")!
        var temp = 0.0
        if let data = try? Data(contentsOf: url),
           let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let current = json["current"] as? [String: Any] {
            temp = current["temp_c"] as? Double ?? 0
        }

        let entry = WeatherEntry(date: .now, temperature: temp)
        completion(Timeline(entries: [entry], policy: .after(.now.addingTimeInterval(1800))))
    }
}

struct WeatherWidgetView: View {
    var entry: WeatherEntry
    var body: some View {
        VStack {
            Text("🌤 Berlin")
            Text("\(entry.temperature, specifier: "%.1f")°C")
                .font(.largeTitle)
        }
        .foregroundStyle(.white)
    }
}

@main
struct WeatherWidget: Widget {
    var body: some WidgetConfiguration {
        StaticConfiguration(kind: "weather_widget", provider: WeatherProvider()) { entry in
            WeatherWidgetView(entry: entry)
        }
        .supportedFamilies([.systemSmall, .systemMedium])
