    func placeholder(in context: Context) -> CounterEntry { CounterEntry(date: .now, count: 0) }
    func getSnapshot(in context: Context, completion: @escaping (CounterEntry) -> ()) { completion(CounterEntry(date: .now, count: CounterStorage.shared.count)) }
    func getTimeline(in context: Context, completion: @escaping (Timeline<CounterEntry>) -> ()) {
        completion(Timeline(entries: [CounterEntry(date: .now, count: CounterStorage.shared.count)], policy: .never))
    }
}

