import WidgetKit
import SwiftUI
import EventKit

struct CalendarEntry: TimelineEntry {
    let date: Date
    let nextEvent: String
}

struct CalendarProvider: TimelineProvider {
    let store = EKEventStore()

    func placeholder(in context: Context) -> CalendarEntry {
        CalendarEntry(date: .now, nextEvent: "Kein Termin")
    }

    func getSnapshot(in context: Context, completion: @escaping (CalendarEntry) -> ()) {
        completion(CalendarEntry(date: .now, nextEvent: "Meeting 14:00"))
    }

    func getTimeline(in context: Context, completion: @escaping (Timeline<CalendarEntry>) -> ()) {
        var next = "Keine Daten"
        store.requestAccess(to: .event) { granted, _ in
            if granted {
                let start = Date()
                let end = Date().addingTimeInterval(60 * 60 * 24)
                let predicate = store.predicateForEvents(withStart: start, end: end, calendars: nil)
                let events = store.events(matching: predicate)
                next = events.first?.title ?? "Keine Termine"
            }
            let entry = CalendarEntry(date: .now, nextEvent: next)
            completion(Timeline(entries: [entry], policy: .after(.now.addingTimeInterval(3600))))
        }
    }
}

struct CalendarWidgetView: View {
    var entry: CalendarEntry
    var body: some View {
        VStack(alignment: .leading) {
            Text("📅 Nächster Termin")
                .font(.headline)
            Text(entry.nextEvent)
                .font(.title3)
        }
        .foregroundStyle(.white)
    }
}

@main
struct CalendarWidget: Widget {
    var body: some WidgetConfiguration {
        StaticConfiguration(kind: "calendar_widget", provider: CalendarProvider()) { entry in
            CalendarWidgetView(entry: entry)
        }
        .supportedFamilies([.systemSmall, .systemMedium])
        .configurationDisplayName("Kalender Widget")
        .description("Zeigt deinen nächsten Termin an.")
    }
}

