        let days = Calendar.current.dateComponents([.day], from: .now, to: target).day ?? 0
        let entry = CountdownEntry(date: .now, remaining: days)
        completion(Timeline(entries: [entry], policy: .after(.now.addingTimeInterval(3600))))
    }
}

