import WidgetKit
import SwiftUI
import HealthKit

struct StepsEntry: TimelineEntry {
    let date: Date
    let steps: Int
}

class HealthManager {
    static let shared = HealthManager()
    let hk = HKHealthStore()
}

struct StepsProvider: TimelineProvider {
    func placeholder(in context: Context) -> StepsEntry { StepsEntry(date: .now, steps: 0) }
    func getSnapshot(in context: Context, completion: @escaping (StepsEntry) -> ()) { completion(StepsEntry(date: .now, steps: 5000)) }

    func getTimeline(in context: Context, completion: @escaping (Timeline<StepsEntry>) -> ()) {
        let type = HKQuantityType.quantityType(forIdentifier: .stepCount)!
        let now = Date()
        let start = Calendar.current.startOfDay(for: now)

        let query = HKStatisticsQuery(quantityType: type, quantitySamplePredicate: nil, options: .cumulativeSum) { _, stats, _ in
            let steps = Int(stats?.sumQuantity()?.doubleValue(for: .count()) ?? 0)
            let entry = StepsEntry(date: now, steps: steps)
            completion(Timeline(entries: [entry], policy: .after(now.addingTimeInterval(1800))))
        }

        HealthManager.shared.hk.execute(query)
    }
}

